export type GameIconId = keyof typeof GAME_ICONS;

export function isGameIconId(value: unknown): value is GameIconId {
  return typeof value === "string" && Object.hasOwn(GAME_ICONS, value);
}

/**
 * Each bestiary monster's icon, by monster id. A test checks that every
 * monster in the bestiary has one.
 */
export const MONSTER_ICONS: Readonly<Record<string, GameIconId>> = {
  "bandit-captain": "hood",
  bandit: "bandit",
  "brown-bear": "bear-head",
  "bugbear-warrior": "brute",
  "dire-wolf": "wolf-head",
  "giant-rat": "rat",
  "giant-spider": "spider-alt",
  ghoul: "raise-zombie",
  gnoll: "hyena-head",
  "goblin-boss": "goblin",
  "goblin-minion": "goblin",
  "goblin-warrior": "goblin",
  "hobgoblin-warrior": "orc-head",
  kobold: "lizardman",
  mastiff: "sitting-dog",
  ogre: "ogre",
  owlbear: "owl",
  skeleton: "skeleton",
  "warrior-veteran": "visored-helm",
  wolf: "wolf-howl",
  zombie: "shambling-zombie",
};

/** An opponent with an inline stat block and no icon of its own. */
export const OPPONENT_ICON: GameIconId = "crossed-swords";

/** Each catalogue item's icon; a +1 item has its base item's. */
const CATALOGUE_ICONS: Readonly<
  Record<MundaneWeaponId | MundaneArmourId | ToolId | AmmunitionId, GameIconId>
> = {
  club: "wood-club",
  dagger: "plain-dagger",
  mace: "flanged-mace",
  quarterstaff: "wizard-staff",
  shortsword: "pointy-sword",
  longsword: "broadsword",
  greatsword: "two-handed-sword",
  shortbow: "pocket-bow",
  "light-crossbow": "crossbow",
  longbow: "bow-arrow",
  leather: "leather-armor",
  "chain-shirt": "mail-shirt",
  "chain-mail": "chain-mail",
  plate: "breastplate",
  shield: "bordered-shield",
  "thieves-tools": "lockpicks",
  arrows: "quiver",
  bolts: "arrowhead",
};

export function catalogueIcon(id: CatalogueId): GameIconId {
  const base = (magicOf(id)?.base ?? id) as keyof typeof CATALOGUE_ICONS;
  return CATALOGUE_ICONS[base];
}

/** Coin, in the purse or found. */
export const COIN_ICON: GameIconId = "two-coins";
/** A gem or art object kept from an earlier adventure, whose kind is not kept. */
export const TREASURE_ICON: GameIconId = "chest";
export const SCROLL_ICON: GameIconId = "scroll-unfurled";
export const WAND_ICON: GameIconId = "fairy-wand";

/** An adventure module's item's icon, by its kind. */
export function itemIcon(item: FifthItem): GameIconId {
  switch (item.kind) {
    case "coin":
      return COIN_ICON;
    case "gear":
      return catalogueIcon(item.gear!);
    case "treasure":
      return item.treasure!.startsWith("gem")
        ? "cut-diamond"
        : "jeweled-chalice";
    case "scroll":
      return SCROLL_ICON;
    case "wand":
    case "caster-item":
      // Every caster item is a wand so far (#537).
      return WAND_ICON;
    case "key":
      return "key";
    case "tool":
      return "toolbox";
    default:
      // Every other kind is a potion.
      return "health-potion";
  }
}

/** Every icon as an SVG `<symbol>`, for the page to `<use>` by `#icon-<id>`. */
export function iconSprite(): string {
  return `<svg xmlns="http://www.w3.org/2000/svg" hidden>${Object.entries(
    GAME_ICONS,
  )
    .map(
      ([id, icon]) =>
        `<symbol id="icon-${id}" viewBox="0 0 512 512"><path d="${icon.path}"/></symbol>`,
    )
    .join("")}</svg>`;
}

/** The credit CC BY 3.0 asks for: every artist with an icon here. */
export function iconCredits(): string {
  const artists = [
    ...new Set(Object.values(GAME_ICONS).map(({ artist }) => artist)),
  ].sort();
  return `Icons by ${artists.join(", ")}, from game-icons.net under CC BY 3.0.`;
}
